{
  "name": "omnibar-shortcuts",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "build:chrome": "vite build --mode chrome",
    "build:firefox": "vite build --mode firefox",
    "build:all": "npm run build:chrome && npm run build:firefox"
  },
  "devDependencies": {
    "@types/chrome": "^0.0.267",
    "@crxjs/vite-plugin": "^2.0.0",
    "typescript": "^5.5.4",
    "vite": "^5.4.0"
  }
}

type BrowserTarget = 'chrome' | 'firefox';

type Manifest = chrome.runtime.ManifestV3;

const BASE_PERMISSIONS: Manifest['permissions'] = [
  'storage',
  'tabs',
  'contextMenus',
  'webNavigation',
  'declarativeNetRequest',
  'declarativeNetRequestWithHostAccess',
];

export default function createManifest(target: BrowserTarget): Manifest {
  const isFirefox = target === 'firefox';

  const manifest: Manifest = {
    manifest_version: 3,
    name: 'Omnibar Shortcuts',
    version: '0.1.0',
    description:
      'Instant address-bar shortcuts for redirects, bundles, and dynamic searches.',
    action: {
      default_title: 'Omnibar Shortcuts',
      default_popup: 'src/popup.html',
    },
    background: {
      service_worker: 'src/background.ts',
      type: 'module',
    },
    permissions: BASE_PERMISSIONS,
    host_permissions: ['<all_urls>'],
    minimum_chrome_version: '120',
  };

  if (isFirefox) {
    (manifest as Manifest & {
      browser_specific_settings?: {
        gecko?: { id: string; strict_min_version?: string };
      };
    }).browser_specific_settings = {
      gecko: {
        id: 'omnibar-shortcuts@example.com',
        strict_min_version: '128.0',
      },
    };
  }

  return manifest;
}

